import { test } from "node:test";
import * as fs from "node:fs"; import * as os from "node:os"; import * as path from "node:path";
import { AutonomousAgent } from "../src/agent.js";
import { DurableStateManager } from "../src/core/state.js";
import { fakeClock, startGateway } from "./helpers/provider_fixture.js";
const workspace = fs.mkdtempSync(path.join(os.tmpdir(), "zz-r6-"));
test("probe", async () => {
  const gw = await startGateway(() => ({ kind: "tools", calls: [{ name: "task_completed", args: { summary: "report" } }] }));
  try {
    const rows: string[] = [];
    for (const mode of ["default", "readonly-explicit", "auto"]) for (const role of ["semantic_explorer","call_site_analyzer","security_reviewer","acceptance_reviewer","reviewer","researcher","failure_debugger","tester","implementer","architect"]) {
      const stateDir = fs.mkdtempSync(path.join(os.tmpdir(), "zz-r6s-"));
      const cfg: any = { endpoint: gw.url, model: "m", maxSteps: 3, temperature: 0, workspace, shell: "bash", role };
      if (mode === "readonly-explicit") { cfg.readOnly = true; cfg.approvalMode = "read-only"; }
      if (mode === "auto") { cfg.approvalMode = "auto"; }
      const make = () => { const a = new AutonomousAgent({ ...cfg }, 1, undefined, { durable: true, role } as any) as any; a.recoveryClock = fakeClock(); a.stateManager = new DurableStateManager({ baseDir: stateDir, workspacePaths: [a.primaryWorkspacePathIdentity] }); return a; };
      const first = make(); const id = first.getTaskId(); first.checkpointDurableState("c"); first.shutdown();
      const second = make(); await second.recoverFromTaskState(id);
      const pend = second.hasPendingModifications;
      let outcome = "?"; try { const t = await second.runTurn("report", undefined, { resume: true }); outcome = String(t.outcome); } catch (e: any) { outcome = "ERR " + e.message.slice(0, 40); }
      rows.push(`${mode.padEnd(18)} ${role.padEnd(20)} pending=${pend} outcome=${outcome}`);
      second.shutdown();
    }
    console.log(rows.join("\n"));
  } finally { await gw.close(); }
});
